cd /workspace && cat > src/repository.py <<'EOF'
def initialize(connection):
    connection.executescript("CREATE TABLE accounts(id TEXT PRIMARY KEY, balance INTEGER NOT NULL); CREATE TABLE ledger(source TEXT, target TEXT, amount INTEGER);")
    connection.commit()

def balance(connection, account):
    row = connection.execute("SELECT balance FROM accounts WHERE id=?", (account,)).fetchone()
    return None if row is None else row[0]

def move(connection, source, target, amount):
    # Guarded debit: the row is only updated if the source still covers the amount,
    # so a concurrent writer cannot overdraw between validation and this write.
    debited = connection.execute(
        "UPDATE accounts SET balance=balance-? WHERE id=? AND balance>=?",
        (amount, source, amount)).rowcount
    if debited != 1:
        raise ValueError("insufficient funds or unknown source account")
    credited = connection.execute(
        "UPDATE accounts SET balance=balance+? WHERE id=?", (amount, target)).rowcount
    if credited != 1:
        raise ValueError("unknown target account")
    connection.execute("INSERT INTO ledger VALUES (?, ?, ?)", (source, target, amount))
EOF
cat > src/service.py <<'EOF'
from .repository import balance, move

def _validate(connection, source, target, amount):
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError("amount must be an integer")
    if amount <= 0:
        raise ValueError("amount must be positive")
    if source == target:
        raise ValueError("source and target must differ")
    source_balance = balance(connection, source)
    if source_balance is None:
        raise ValueError("unknown source account")
    if balance(connection, target) is None:
        raise ValueError("unknown target account")
    if amount > source_balance:
        raise ValueError("amount exceeds source balance")

def transfer(connection, publisher, source, target, amount):
    try:
        _validate(connection, source, target, amount)
        move(connection, source, target, amount)
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    # Published only after a successful commit. A failure here propagates
    # but does not roll back the committed transfer.
    publisher.publish({"source": source, "target": target, "amount": amount})
EOF
